"""Read-only prioritization of unresolved bank source pixels, never material assignment."""
import argparse,hashlib,json
from pathlib import Path
import numpy as np
from PIL import Image,ImageDraw
from scipy.ndimage import label,find_objects
R=Path(__file__).resolve().parents[3];B=R/'level-editor/work/croisement03-refinement';W=B/'restart2'
def main():
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);out=p.parse_args().output;assert not(out/'receipt.json').exists();out.mkdir(exist_ok=True);pins={}
 def pin(path):pins[str(path)]=hashlib.sha256(path.read_bytes()).hexdigest();return path
 prior=json.loads(pin(W/'bank-full-visible-stone-audit-v3/receipt.json').read_text());classes=np.array(Image.open(pin(W/'bank-full-visible-stone-audit-v3/accounting-classes.png')));residual=classes==1;assert int(residual.sum())==42185;src=np.array(Image.open(pin(B/'baseline/covered.png')).convert('RGB'));revealed=np.array(Image.open(pin(B/'baseline/revealed.png')).convert('RGB'));assert pins[str(B/'baseline/covered.png')]==prior['pins'][str(B/'baseline/covered.png')]
 for filename in ['covered-revealed-native-context.png','whole-bank-source-and-overlay.png']:pin(W/'bank-full-visible-stone-audit-v3'/filename)
 # Polygons locate evidence for human review, not accepted source domains or physical owners.
 patches=[
 ('east-cap-shoulder-window','stone_window_review',1,[[554,225],[562,227],[569,232],[568,239],[561,237],[556,230]],'Continuous pale/gray stone shoulder behind small leaf fringe. Most useful small missing-source window; preserve twig at left boundary.'),
 ('central-upper-window-a','stone_window_review',2,[[351,214],[361,215],[364,218],[360,220],[352,218]],'Short exposed-gray band between gold leaf specks; narrow patch avoids bright lower leaf tips.'),
 ('central-upper-window-b','stone_window_review',2,[[369,216],[377,219],[377,222],[372,224],[368,221]],'Small sloping gray face; upper/lower gold specks and thin shadow remain outside proposed review interior.'),
 ('central-upper-window-c','stone_window_review',2,[[386,218],[394,218],[397,222],[394,225],[388,223]],'Stone-looking gap immediately above lower gold cluster. Tiny source window, not new rock geometry.'),
 ('south-high-window','stone_window_review',3,[[337,337],[345,338],[347,344],[342,348],[336,345]],'Pale southern stone patch between ivy/twigs; foliage crosses edges. Must inspect exact pixels, not accept whole connected residual component.'),
 ('south-right-small-window','stone_window_review',3,[[389,349],[397,350],[400,353],[395,355],[389,353]],'Small pale ledge above previously proposed southern window; native phase reservations remain priority.'),
 ('west-cap-dark-contact','dark_joint_or_boundary_review',1,[[151,241],[169,251],[190,262],[211,272],[230,267],[251,253],[262,252],[251,263],[230,278],[213,282],[193,272],[171,259],[151,252]],'Residual band is mainly dark cap/stack joint, not a missing broad stone strip. Tiny illuminated rock lips need separate exact tracing.'),
 ('west-cap-top-silhouette','dark_joint_or_boundary_review',2,[[157,196],[171,179],[191,168],[213,167],[236,172],[256,175],[271,173],[265,180],[242,180],[216,174],[194,174],[176,183],[165,199]],'Thin outer contour mixes rock rim and background shadow; do not grow stone by dilating previous polygon.'),
 ('east-cheek-cleft','dark_joint_or_boundary_review',2,[[610,204],[618,202],[620,223],[615,248],[621,281],[610,301],[600,299],[609,280],[607,255],[612,234]],'Right cheek boundary and dark crevice; some lit border pixels may be stone, deeper black must remain unclassified.'),
 ('west-ivy-foreground','vegetation_context_review',3,[[210,328],[243,328],[276,342],[313,357],[312,388],[291,411],[258,414],[226,400],[209,375]],'Dense gold/green ivy and low vegetation in front of bank; not rock fill context. Some hidden stone may exist behind it, but these source pixels show plants.'),
 ('east-ivy-foreground','vegetation_context_review',3,[[470,346],[498,337],[529,344],[551,365],[548,400],[522,422],[481,420],[460,400]],'Dense green ivy/gold foliage beside Tree18. Leaf texture and twigs are observed; hidden rock is not recoverable from alpha complement.'),
 ('south-foot-vegetation','vegetation_context_review',3,[[320,446],[340,441],[370,447],[391,462],[408,471],[402,480],[366,477],[339,469],[316,458]],'Basal grass/ivy and root-edge context. Do not use as stone donor or infer broad stone footprint.'),
 ('east-neighbor-stone-context','neighbor_context_review',3,[[624,239],[641,232],[664,234],[684,248],[687,270],[673,289],[649,290],[631,282],[621,264]],'Clearly visible adjacent boulder stack across dark cleft; likely separate context, no52/53/54 assignment established.'),
 ('far-east-vegetation-context','vegetation_context_review',3,[[685,305],[707,294],[731,299],[744,322],[738,346],[716,358],[686,344]],'Far-right tree/bank-edge vegetation context included by broad mask extent; not evidence of missing main-bank stone.'),
 ('west-neighbor-stone-context','neighbor_context_review',3,[[101,269],[114,261],[129,262],[139,273],[137,285],[119,291],[104,283]],'Left isolated boulder surface across seam; distinct neighbor context with ownership unresolved, not automatic53 expansion.')]
 def poly(points):
  im=Image.new('L',(src.shape[1],src.shape[0]));ImageDraw.Draw(im).polygon([tuple(x)for x in points],fill=255);return np.array(im)>0
 proposed=np.zeros(classes.shape,np.uint8);types=['stone_window_review','dark_joint_or_boundary_review','vegetation_context_review','neighbor_context_review'];rows=[];marked=src.copy();palette=[[0,235,240],[255,100,190],[75,210,85],[160,110,250]]
 for name,kind,priority,points,note in patches:
  raw=poly(points);mask=raw&residual;ids=np.argwhere(mask);rows.append({'id':name,'type':kind,'priority':priority,'polygon':points,'source_bounds_xyxy':[min(p[0]for p in points),min(p[1]for p in points),max(p[0]for p in points)+1,max(p[1]for p in points)+1],'residual_pixels_in_patch':int(mask.sum()),'nonresidual_pixels_excluded':int((raw&~residual).sum()),'notes':note,'status':'HUMAN_REVIEW_ONLY_NO_PIXEL_ASSIGNMENT'});index=types.index(kind);assert not np.any(proposed[mask]),name;proposed[mask]=index+1;marked[mask]=(.35*marked[mask]+.65*np.array(palette[index])).astype('uint8')
  if priority<=2 or kind=='stone_window_review':
   x0,y0,x1,y1=rows[-1]['source_bounds_xyxy'];box=(x0-6,y0-6,x1+6,y1+6);scale=6;w,h=(box[2]-box[0])*scale,(box[3]-box[1])*scale;sheet=Image.new('RGB',(w*2,h+25),'#303030');sheet.paste(Image.fromarray(src).crop(box).resize((w,h),Image.Resampling.NEAREST),(0,25));sheet.paste(Image.fromarray(marked).crop(box).resize((w,h),Image.Resampling.NEAREST),(w,25));ImageDraw.Draw(sheet).text((3,5),f'{name} / crop{box}',fill='white');sheet.save(out/f'{name}.png')
 counts={name:int((proposed==i+1).sum())for i,name in enumerate(types)};counts['still_unresolved']=int((residual&(proposed==0)).sum());assert sum(counts.values())==42185;Image.fromarray(proposed).save(out/'residual-review-classes.png')
 labels,n=label(residual);components=[]
 for i,slices in enumerate(find_objects(labels),1):
  if slices is None:continue
  component=labels[slices]==i;parts=proposed[slices][component];components.append({'component':i,'pixels':int(component.sum()),'bbox_xyxy':[slices[1].start,slices[0].start,slices[1].stop,slices[0].stop],'review_counts':{name:int((parts==j+1).sum())for j,name in enumerate(types)},'remaining':int((parts==0).sum())})
 components.sort(key=lambda x:-x['pixels']);assert sum(c['pixels']for c in components)==42185
 box=(90,140,750,480);scale=2;w,h=(box[2]-box[0])*scale,(box[3]-box[1])*scale;sheet=Image.new('RGB',(w*2,h+25),'#303030');sheet.paste(Image.fromarray(src).crop(box).resize((w,h),Image.Resampling.NEAREST),(0,25));sheet.paste(Image.fromarray(marked).crop(box).resize((w,h),Image.Resampling.NEAREST),(w,25));draw=ImageDraw.Draw(sheet);draw.text((3,5),'Original source; v3 untouched',fill='white');draw.text((w+3,5),'Cyan stone-window review / pink seams / green vegetation / violet neighbor context',fill='white');sheet.save(out/'prioritized-source-patches.png')
 report={'status':'RESIDUAL_SOURCE_CONTEXT_PRIORITIES_NOT_ACCEPTED_DOMAINS','pins':pins,'starting_residual':42185,'counts':counts,'patches':rows,'connected_component_count':n,'components':components,'covered_revealed_differences_on_residual':int((residual&np.any(src!=revealed,axis=2)).sum()),'priority_findings':['East-cap shoulder and six small central/south windows have exposed stone-looking source beyond earlier proposal; these are pixel-review priorities, not newly assigned owners.','Large residual west-cap band primarily follows dark joints and silhouette boundaries. Do not recover it by uniform stone dilation.','Three largest residual connected components mix stone, vegetation, neighbor objects and shadow. Connectivity cannot establish material or owner.','Substantial residual texture is foreground vegetation; visible adjacent west/east stone is separate context until ownership proven.','All v3 proposals, boundaries, native reservations and manual uncertainties remain untouched; this audit intersects only class1.'],'remaining':['Fine stone windows still require independent exact source review then saved receiver tests.','Bright leaves and thin twigs can remain inside any tiny proposed window; review crops before accepting pixels.','Remaining source-context classification is intentionally incomplete where material/ownership cannot be defended. Hidden3D continuation is not represented by residual2D pixels.'],'limits':['No alpha/color segmentation, source assignment, geometry/model edit or API generation.','Class labels mean review categories only, including vegetation/context proposals; they do not alter map ownership.']};(out/'receipt.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'counts':counts,'components':n,'windows':[(r['id'],r['residual_pixels_in_patch'])for r in rows[:6]]}))
if __name__=='__main__':main()
